/**
 * Entry for the barcode-scanner pages ({,ca/,eu/,gl/}lectores/…), generated by
 * scripts/gen-scanners.mjs. Content is baked into each shell; this only mounts
 * the shared chrome (lib/static-page).
 */
import './styles/fonts.css';
import './styles/tokens.css';
import './styles/app.css';
import './styles/faq.css';
import './styles/scanners.css';
import { type Lang } from './lib/i18n';
import { mountStaticPage, scannersHref } from './lib/static-page';

const BASE = import.meta.env.BASE_URL;
// The generated shell bakes <html lang>; it's the source of truth here.
const lang = (document.documentElement.lang || 'es') as Lang;

// Language links keep the reader on the same page: swap the locale segment of
// the path after the base (/farma-kit/ca/lectores/x/ → /farma-kit/eu/lectores/x/).
const rest = location.pathname.startsWith(BASE) ? location.pathname.slice(BASE.length) : '';
const sub = rest.replace(/^(ca|eu|gl)\//, '').replace(/^lectores\/?/, '').replace(/index\.html$/, '');
const langHref = (l: string) => `${scannersHref(l)}${sub}`;

mountStaticPage({ lang, langHref, faqHref: `${scannersHref(lang)}#faq`, active: 'scanners' });
